{"file_text": "@page "/settings"
@using sv_a1f6c1a21cef459caa0c97f5aab5836d.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => SetActiveSection(section.Key)">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span>@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            <!-- Toast notification -->
            @if (_showToast)
            {
                <div class="toast-notification @(_toastType)">
                    <span>@_toastMessage</span>
                    <button class="toast-close" @onclick="DismissToast">✕</button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }
    </div>
</div>

@* ────────────── Profile Section ────────────── *@
@{
    RenderFragment RenderProfile() =>
        @<section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your personal information and public profile.</p>

            <div class="avatar-area">
                <img src="@_editProfile.AvatarUrl" alt="Avatar" class="avatar-preview" />
                <span class="avatar-url-label">@_editProfile.AvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_editProfile.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_editProfile.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="_editProfile.Bio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Changes")
                </button>
                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>;
}

@* ────────────── Notifications Section ────────────── *@
@{
    RenderFragment RenderNotifications() =>
        @<section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editNotifications.EmailNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>
                <label class="toggle-row">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editNotifications.PushNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>
                <label class="toggle-row">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editNotifications.WeeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h4>Muted Channels</h4>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _editNotifications.MutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleMuteChannel(channel, (bool)(e.Value ?? false))" />
                        <span>#@channel</span>
                        @if (isMuted)
                        {
                            <span class="muted-badge">muted</span>
                        }
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Preferences")
                </button>
            </div>
        </section>;
}

@* ────────────── Security Section ────────────── *@
@{
    RenderFragment RenderSecurity() =>
        @<section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Protect your account with passwords and session management.</p>

            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <div class="error-message">@_passwordError</div>
                        }
                        <button class="btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                            @(_saving ? "Updating…" : "Update Password")
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="toggle-group" style="margin-top:1.5rem;">
                <label class="toggle-row">
                    <span>
                        Two-Factor Authentication
                        @if (_securitySettings?.TwoFactorEnabled == true)
                        {
                            <span class="status-badge enabled">Enabled</span>
                        }
                        else
                        {
                            <span class="status-badge disabled">Disabled</span>
                        }
                    </span>
                    <label class="switch">
                        <input type="checkbox" checked="@(_securitySettings?.TwoFactorEnabled ?? false)"
                               @onchange="Toggle2FA" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="last-changed">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <!-- Active Sessions -->
            <h4 style="margin-top:1.5rem;">Active Sessions</h4>
            @if (_securitySettings?.Sessions.Count > 0)
            {
                <div class="table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _securitySettings.Sessions[0].Id)
                                        {
                                            <button class="btn-danger-sm"
                                                    @onclick="() => PromptRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p>No active sessions.</p>
            }

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h4>Revoke Session</h4>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                        <div class="button-row">
                            <button class="btn-danger" @onclick="ConfirmRevokeSession">Revoke</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>;
}

@* ────────────── Appearance Section ────────────── *@
@{
    RenderFragment RenderAppearance() =>
        @<section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize the look and feel of the application.</p>

            <h4>Theme</h4>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_editAppearance.Theme == theme)"
                               @onchange="() => _editAppearance.Theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>

            <h4>Font Size</h4>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_editAppearance.FontSize == size)"
                               @onchange="() => _editAppearance.FontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_editAppearance.Language">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Portuguese">Portuguese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Compact Mode</span>
                    <label class="switch">
                        <input type="checkbox" @bind="_editAppearance.CompactMode" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <!-- Live Preview -->
            <h4>Preview</h4>
            <div class="appearance-preview @(_editAppearance.Theme.ToLowerInvariant()) @(_editAppearance.CompactMode ? "compact" : "")"
                 style="font-size:@GetPreviewFontSize()">
                <div class="preview-header">
                    <strong>Dashboard</strong>
                    <span class="preview-badge">@_editAppearance.Theme Theme</span>
                </div>
                <p>This is a preview of your selected appearance settings.</p>
                <div class="preview-card">
                    <span>📊 Analytics</span>
                    <span class="preview-meta">Font: @_editAppearance.FontSize · Lang: @_editAppearance.Language</span>
                </div>
                <div class="preview-card">
                    <span>📋 Tasks</span>
                    <span class="preview-meta">Compact: @(_editAppearance.CompactMode ? "On" : "Off")</span>
                </div>
            </div>

            <div class="button-row">
                <button class="btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>
            </div>
        </section>;
}

@code {
    // ── Section navigation ──
    private string ActiveSection { get; set; } = "profile";

    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨")
    };

    // ── Shared state ──
    private bool _loading = true;
    private bool _saving;
    private bool _showToast;
    private string _toastMessage = "";
    private string _toastType = "success";
    private System.Timers.Timer? _toastTimer;

    // ── Profile state ──
    private ProfileEditModel _editProfile = new();
    private UserProfile? _savedProfile;

    // ── Notifications state ──
    private NotificationsEditModel _editNotifications = new();
    private readonly List<string> _allChannels = ["announcements", "random", "off-topic", "watercooler", "design-reviews"];

    // ── Security state ──
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private ActiveSession? _sessionToRevoke;

    // ── Appearance state ──
    private AppearanceEditModel _editAppearance = new();

    // ── Mutable edit models (records are immutable) ──
    private class ProfileEditModel
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }

    private class NotificationsEditModel
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = [];
    }

    private class AppearanceEditModel
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfileToEdit(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _editNotifications = new NotificationsEditModel
        {
            EmailNotifications = notifs.EmailNotifications,
            PushNotifications = notifs.PushNotifications,
            WeeklyDigest = notifs.WeeklyDigest,
            MutedChannels = new List<string>(notifs.MutedChannels)
        };

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();

        var appearance = await SettingsService.GetAppearanceAsync();
        _editAppearance = new AppearanceEditModel
        {
            Theme = appearance.Theme,
            FontSize = appearance.FontSize,
            Language = appearance.Language,
            CompactMode = appearance.CompactMode
        };
    }

    private void ApplyProfileToEdit(UserProfile profile)
    {
        _editProfile = new ProfileEditModel
        {
            DisplayName = profile.DisplayName,
            Email = profile.Email,
            AvatarUrl = profile.AvatarUrl,
            Bio = profile.Bio
        };
    }

    private void SetActiveSection(string section)
    {
        ActiveSection = section;
    }

    // ── Toast helpers ──
    private void ShowToast(string message, string type = "success")
    {
        _toastMessage = message;
        _toastType = type;
        _showToast = true;

        _toastTimer?.Dispose();
        _toastTimer = new System.Timers.Timer(3000);
        _toastTimer.Elapsed += (_, _) =>
        {
            _showToast = false;
            _toastTimer?.Dispose();
            InvokeAsync(StateHasChanged);
        };
        _toastTimer.AutoReset = false;
        _toastTimer.Start();
    }

    private void DismissToast() => _showToast = false;

    // ── Profile actions ──
    private async Task SaveProfile()
    {
        _saving = true;
        var profile = new UserProfile(
            _editProfile.DisplayName,
            _editProfile.Email,
            _editProfile.AvatarUrl,
            _editProfile.Bio
        );
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfileToEdit(_savedProfile);
            ShowToast("Changes discarded.", "info");
        }
    }

    // ── Notifications actions ──
    private void ToggleMuteChannel(string channel, bool muted)
    {
        if (muted && !_editNotifications.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!muted)
            _editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        var prefs = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels)
        );
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _saving = false;
        ShowToast("Notification preferences saved!");
    }

    // ── Security actions ──
    private async Task UpdatePassword()
    {
        _passwordError = "";

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        _saving = true;
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        _saving = false;
        ShowToast("Password updated successfully!");
    }

    private void Toggle2FA(ChangeEventArgs e)
    {
        if (_securitySettings is not null)
        {
            var enabled = (bool)(e.Value ?? false);
            _securitySettings = _securitySettings with { TwoFactorEnabled = enabled };
            ShowToast(enabled ? "Two-factor authentication enabled." : "Two-factor authentication disabled.", "info");
        }
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        ShowToast("Session revoked.");
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Appearance actions ──
    private string GetPreviewFontSize() => _editAppearance.FontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private async Task SaveAppearance()
    {
        _saving = true;
        var settings = new AppearanceSettings(
            _editAppearance.Theme,
            _editAppearance.FontSize,
            _editAppearance.Language,
            _editAppearance.CompactMode
        );
        await SettingsService.SaveAppearanceAsync(settings);
        _saving = false;
        ShowToast("Appearance settings saved!");
    }

    public void Dispose()
    {
        _toastTimer?.Dispose();
    }
}
